/**
 * Errors surfaced from the on-device store to the foreign side.
 *
 * The variants mirror the desktop's `CommandError` codes (the `From<
 * cal_core::Error>` mapping in `src-tauri/src/commands/mod.rs`) so the mobile
 * UI can branch on the same distinctions — re-auth on `Auth`, an
 * optimistic-concurrency retry on `Conflict`, a transient banner on
 * `Network`, etc. — instead of getting one opaque storage error. The
 * external-adapter event paths are where the full spread becomes reachable.
 */
sealed class StoreException: kotlin.Exception() {
    
    /**
     * Opening or migrating the database file failed.
     */
    class Open(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A read or write against the local database (or an unclassified adapter
     * failure) failed.
     */
    class Storage(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The requested row does not exist.
     */
    class NotFound(
        ) : StoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A value coming from the foreign side could not be parsed into the
     * core model (a malformed date, time, datetime, recurrence rule, …) or
     * was otherwise rejected as invalid input.
     */
    class InvalidField(
        
        val `field`: kotlin.String, 
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "field=${ `field` }, detail=${ `detail` }"
    }
    
    /**
     * The adapter rejected the credentials (expired / wrong token) — the UI
     * surfaces the re-connect flow.
     */
    class Auth(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The account is authenticated but not allowed to perform the operation.
     */
    class Forbidden(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * An ETag / precondition-failed clash (the row changed underneath us) —
     * the UI re-reads and retries.
     */
    class Conflict(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A transient network failure reaching the provider.
     */
    class Network(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The provider answered with something the adapter couldn't parse.
     */
    class Protocol(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The adapter doesn't support this operation.
     */
    class Unsupported(
        
        val `detail`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<StoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): StoreException = FfiConverterTypeStoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeStoreError : FfiConverterRustBuffer<StoreException> {
    override fun read(buf: ByteBuffer): StoreException {
        

        return when(buf.getInt()) {
            1 -> StoreException.Open(
                FfiConverterString.read(buf),
                )
            2 -> StoreException.Storage(
                FfiConverterString.read(buf),
                )
            3 -> StoreException.NotFound()
            4 -> StoreException.InvalidField(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> StoreException.Auth(
                FfiConverterString.read(buf),
                )
            6 -> StoreException.Forbidden(
                FfiConverterString.read(buf),
                )
            7 -> StoreException.Conflict(
                FfiConverterString.read(buf),
                )
            8 -> StoreException.Network(
                FfiConverterString.read(buf),
                )
            9 -> StoreException.Protocol(
                FfiConverterString.read(buf),
                )
            10 -> StoreException.Unsupported(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: StoreException): ULong {
        return when(value) {
            is StoreException.Open -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is StoreException.InvalidField -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`field`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.Auth -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.Forbidden -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.Conflict -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.Protocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is StoreException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: StoreException, buf: ByteBuffer) {
        when(value) {
            is StoreException.Open -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.Storage -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.NotFound -> {
                buf.putInt(3)
                Unit
            }
            is StoreException.InvalidField -> {
                buf.putInt(4)
                FfiConverterString.write(value.`field`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.Auth -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.Forbidden -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.Conflict -> {
                buf.putInt(7)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.Network -> {
                buf.putInt(8)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.Protocol -> {
                buf.putInt(9)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is StoreException.Unsupported -> {
                buf.putInt(10)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



